/**
 * parseSparql parses `input`, running the grammar's semantic
 * actions (which write to the parse context) and throwing an `LrParseError`
 * on a syntax error.
 */
export function parseSparql(input: string): void {
  new SparqlLrParser().parse(new SparqlLexer(input));
}
